import {tokens,sources,posts,defaults,initialState,series,quote,portfolio,holdings,statistics,trade,reviewAlert,demoReply} from './model.js';
import {load,save,validateState} from './store.js';

let storage;try{storage=localStorage;}catch{storage={getItem(){throw Error('Storage unavailable');},setItem(){throw Error('Storage unavailable');}};}
const loaded=load(storage);
let state=loaded.state,storageError=loaded.error;
let route=decodeURIComponent(location.hash.slice(1))||'Dashboard',settingsTab='Appearance',range='Today',tokenFilter='',riskFilter='All risks',watchOnly=false,sourceFilter='All sources',postSearch='',chatSearch='',sort='activity',popup=null,modalToken=null,tradeSide='buy',chatBusy=false;
const app=document.querySelector('#app');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-GB',{style:'currency',currency:state.settings.currency,maximumFractionDigits:2}).format(v);
const compact=v=>new Intl.NumberFormat('en-GB',{notation:'compact',maximumFractionDigits:1}).format(v);
const price=v=>v.toFixed(v<.001?7:5);
const signed=v=>`${v>=0?'+':''}${v.toFixed(2)}%`;
const tokenBy=id=>tokens.find(t=>t.id===id);
const age=at=>{const seconds=Math.max(0,Math.floor((Date.now()-at)/1000));return seconds<60?`${seconds}s ago`:seconds<3600?`${Math.floor(seconds/60)}m ago`:`${Math.floor(seconds/3600)}h ago`;};
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',compass:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M16 8l-3 5-5 3 3-5z',wallet:'M3 6h16v14H3z M3 6V4h14v2 M15 11h6v5h-6z',social:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.9',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',search:'M10.5 3a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15 M16 16l5 5',arrow:'M5 12h14 M13 6l6 6-6 6',up:'M5 16l5-5 4 3 6-10 M15 4h5v5',close:'M6 6l12 12 M18 6L6 18',plus:'M12 5v14 M5 12h14',check:'M4 12l5 5L20 6',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',star:'M12 3l2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9z',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',play:'M8 4l13 8-13 8z',pause:'M8 4v16 M16 4v16',copy:'M9 9h12v12H9z M15 6V3H3v12h3',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',archive:'M3 3h18v5H3z M5 8v13h14V8 M9 12h6'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;}
function btn(label,action,extra='',cls=''){return `<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;}
function empty(title,text,action=''){return `<div class="empty">${icon('archive')}<h3>${title}</h3><p>${text}</p>${action}</div>`;}
function commit(redraw=true){storageError=save(storage,state);applyTheme();if(redraw)render();}
function applyTheme(){
 const s=state.settings,root=document.documentElement;
 const themes={Charcoal:['#101113','#191b1e','#222428','#f4f4f5','#92959c','#303238'],Graphite:['#151719','#1e2124','#292d31','#f0f2f4','#9ba2aa','#373c42'],Light:['#eceef0','#f7f8f9','#ffffff','#191c20','#636a74','#d1d5db']};
 const colors=themes[s.theme]||themes.Charcoal;
 ['bg','surface','raised','text','muted','border'].forEach((k,i)=>root.style.setProperty('--'+k,colors[i]));
 for(const [k,v] of Object.entries({accent:s.accent,green:s.profit,red:s.loss,radius:`${Math.min(28,s.radius)}px`,speed:`${Math.min(300,s.motion)}ms`,font:`${Math.max(11,Math.min(18,s.fontSize))}px`,gap:s.density==='Compact'?'20px':'28px',glass:`${100-Math.min(40,s.transparency)}%`,blur:`${Math.min(40,s.blur)}px`,shadow:`${Math.min(60,s.shadow)}px`}))root.style.setProperty('--'+k,v);
 root.style.colorScheme=s.theme==='Light'?'light':'dark';document.body.classList.toggle('acrylic',s.acrylic);document.body.classList.toggle('no-motion',s.reduceMotion);
}
function chart(id='orbit',small=false){
 const points=series(id,64,state.step),w=680,h=small?80:245,min=96,max=119,y=v=>h-30-(v-min)/(max-min)*(h-55),x=i=>13+i*9.6;
 const grid=small?'':[100,105,110,115].map(v=>`<line class="grid" x1="12" y1="${y(v)}" x2="625" y2="${y(v)}"/><text x="637" y="${y(v)+3}">${v.toFixed(1)}</text>`).join('');
 const line=`<path class="price-line" d="${points.map((p,i)=>`${i?'L':'M'}${x(i)} ${y(p.close)}`).join(' ')}"/>`;
 const candles=points.map((p,i)=>{const color=p.close>=p.open?'var(--green)':'var(--red)';return `<g class="candle" stroke="${color}" fill="${color}"><line x1="${x(i)}" x2="${x(i)}" y1="${y(p.high)}" y2="${y(p.low)}"/><rect x="${x(i)-2.6}" y="${Math.min(y(p.open),y(p.close))}" width="5.2" height="${Math.max(1,Math.abs(y(p.close)-y(p.open)))}" stroke="none"/><rect opacity=".18" x="${x(i)-2}" y="${h-14-p.volume*.13}" height="${p.volume*.13}" width="4" stroke="none"/></g>`;}).join('');
 return `<div class="chart-wrap"><svg class="chart ${small?'chart-small':''}" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Simulated ${esc(id)} ${state.settings.chartStyle.toLowerCase()} chart, normalised index, not historical data" data-chart="${esc(id)}">${grid}${small||state.settings.chartStyle==='Line'?line:candles}</svg>${small?'':`<div class="chart-tooltip" hidden></div><div class="chart-caption"><span>12:00</span><span>12:20</span><span>12:40</span><span>13:00 · synthetic index</span></div>`}</div>`;
}
function tokenCell(t){return `<div class="token"><span class="coin" style="color:${t.color}">${esc(t.symbol[0])}</span><button class="token-name" data-action="token" data-id="${t.id}"><strong>${t.symbol}</strong><small>${t.name}</small></button></div>`;}
function tokenTable(list,full=false){return `<div class="table-scroll"><table><thead><tr><th aria-label="Watchlist"></th><th>Token</th><th>Price · ${state.settings.currency}</th><th>24h change</th><th>Liquidity</th>${full?'<th>Volume · 24h</th><th>Age</th>':''}<th>Research status</th><th></th></tr></thead><tbody>${list.map(t=>`<tr><td>${btn(icon('star'),'watch',`data-id="${t.id}" aria-label="${state.watchlist.includes(t.id)?'Unsave':'Save'} ${t.symbol}" aria-pressed="${state.watchlist.includes(t.id)}"`, `star ${state.watchlist.includes(t.id)?'saved':''}`)}</td><td>${tokenCell(t)}</td><td class="mono">${price(quote(t,state.step))}</td><td class="${t.change>=0?'positive':'negative'}">${signed(t.change)}</td><td>${compact(t.liquidity)}</td>${full?`<td>${compact(t.volume)}</td><td class="muted">${t.age}</td>`:''}<td><span class="pill ${t.risk==='Critical'?'red':t.signal==='HIGH INTEREST'?'blue':''}">${t.signal}</span></td><td>${btn(icon('arrow'),'token',`data-id="${t.id}" aria-label="Inspect ${t.symbol}"`,'icon-btn')}</td></tr>`).join('')}</tbody></table>${list.length?'':empty('No matching tokens','Try another search or risk filter.')}</div>`;}
function heading(title,sub,controls=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="toolbar">${controls}</div></div>`;}
function metrics(items){return `<div class="metrics">${items.map(([label,value,note,cls=''])=>`<div class="metric"><div class="eyebrow">${label}</div><div class="value ${cls}">${value}</div><small>${note}</small></div>`).join('')}</div>`;}
function rangeControl(){return `<div class="segment" aria-label="Time range">${['Today','7 days','30 days','90 days','All time'].map(r=>btn(r,'range',`data-id="${r}" aria-pressed="${range===r}"`,range===r?'selected':'')).join('')}</div>`;}
function statisticsPanel(){const today=new Date();today.setHours(0,0,0,0);const since=range==='All time'?0:range==='Today'?today.getTime():Date.now()-Number.parseInt(range)*86400000;const s=statistics(state,since);return `<section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Closed trade statistics</h2><small>${range} · ${s.count} sell fills · fee-inclusive average cost</small></div><div class="setting-group">${[['Win rate',s.winRate===null?'No sells yet':signed(s.winRate).replace('+','')],['Average gain',money(s.averageGain)],['Average loss',money(s.averageLoss)],['Largest gain',money(s.largestGain)],['Largest loss',money(s.largestLoss)],['Total realised losses',money(s.totalLoss)],['Realised P&L in period',money(s.realised)]].map(([k,v])=>`<div class="source-row"><span>${k}</span><strong class="mono">${v}</strong></div>`).join('')}</div></section>`;}
function alertCard(a){const t=tokenBy(a.token),r=reviewAlert(a,quote(t,state.step));return `<div class="alert-item"><div class="spread"><span class="pill ${r.expired?'':'blue'}">${r.expired?'SIGNAL EXPIRED':t.signal}</span><small class="muted">${age(a.created)}</small></div><button class="open-alert" data-action="alert" data-id="${a.id}">${tokenCellLabel(t)}</button><p>${esc(a.reason)}</p><div class="spread"><span class="${r.move>=0?'positive':'negative'} mono">${signed(r.move)} since alert</span><small class="muted">Simulated</small></div></div>`;}
function tokenCellLabel(t){return `<span class="row"><span class="coin" style="color:${t.color}">${t.symbol[0]}</span><span><strong>${t.symbol}</strong><br><small class="muted">${t.name}</small></span></span>`;}
function dashboard(){const p=portfolio(state),pending=state.alerts.filter(a=>a.status==='Pending');return heading('Your market, in focus.','A quieter view of the signals that deserve a closer look.',btn(icon(state.settings.simulation?'pause':'play')+(state.settings.simulation?' Pause simulation':' Play simulation'),'simulation','', 'ghost')+btn(icon('plus')+' Test alert','test-alert','', 'primary'))+
 metrics([['Practice portfolio',money(p.value),`${money(state.cash)} available`],['Research watchlist',`${state.watchlist.length} <span class="muted" style="font-size:14px">tokens</span>`,'Saved locally on this device'],['Pending alerts',pending.length,'Invented research scenarios'],['Data environment','Simulation','No external feeds connected']])+`<div class="dashboard-grid"><div><section class="panel chart-panel"><div class="panel-head"><div class="row">${tokenCell(tokens[0])}<span class="pill">SIMULATED</span></div><div class="segment">${['Candles','Line'].map(v=>btn(v,'chart-style',`data-id="${v}"`,state.settings.chartStyle===v?'selected':'')).join('')}</div></div><div class="chart-summary"><strong class="mono">${price(quote(tokens[0],state.step))}</strong><span class="positive">+18.42%</span><span class="muted">${state.settings.currency} · invented price</span></div>${chart()}<div class="panel-body spread divider" style="padding-top:13px"><span class="signal-note">${icon('shield')} Evidence before interpretation.</span>${btn('Inspect ORBIT '+icon('arrow'),'token','data-id="orbit"','text-button')}</div></section><section class="panel"><div class="panel-head"><h2>On your radar</h2>${btn('Discover all '+icon('arrow'),'navigate','data-id="Discovery"','text-button')}</div>${tokenTable(tokens.slice(0,4))}</section></div><aside class="stack dashboard-aside"><section class="panel"><div class="panel-head"><h2>Research alerts</h2><span class="pill">${pending.length} new</span></div>${state.alerts.filter(a=>a.status!=='Dismissed').slice(0,2).map(alertCard).join('')||empty('All clear','Use Test alert to create a sample.')}<div class="panel-body divider" style="padding-top:13px">${btn('Open notification centre '+icon('arrow'),'navigate','data-id="Notifications"','text-button')}</div></section><section class="panel"><div class="panel-head"><h2>Source health</h2>${icon('social')}</div><div class="panel-body">${sources.slice(0,4).map(s=>`<div class="source-row"><span>${s}</span><small>Not connected</small></div>`).join('')}<div style="padding-top:10px">${btn('Review connectors '+icon('arrow'),'navigate','data-id="Data health"','text-button')}</div></div></section></aside></div>`;}
function discovery(){let list=tokens.filter(t=>(!watchOnly||state.watchlist.includes(t.id))&&(`${t.symbol} ${t.name}`).toLowerCase().includes(tokenFilter.toLowerCase())&&(riskFilter==='All risks'||t.risk===riskFilter));list=[...list].sort((a,b)=>sort==='liquidity'?b.liquidity-a.liquidity:sort==='change'?b.change-a.change:b.social-a.social);return heading('Token discovery','Explore fictional Solana tokens. Names, values and signals are test fixtures.',btn(icon('star')+' Watchlist','watch-only',`aria-pressed="${watchOnly}"`,watchOnly?'primary':'ghost'))+`<section class="panel"><div class="filterbar"><span class="muted">${icon('search')}</span><input id="token-search" aria-label="Filter tokens" placeholder="Search token or symbol…" value="${esc(tokenFilter)}"><select id="risk-filter" aria-label="Risk filter">${['All risks','Elevated','High','Critical'].map(v=>`<option ${riskFilter===v?'selected':''}>${v}</option>`).join('')}</select><select id="sort" aria-label="Sort tokens"><option value="activity" ${sort==='activity'?'selected':''}>Social activity</option><option value="liquidity" ${sort==='liquidity'?'selected':''}>Liquidity</option><option value="change" ${sort==='change'?'selected':''}>Price change</option></select><span class="grow"></span><small class="muted">${list.length} tokens · simulation</small></div>${tokenTable(list,true)}</section><div class="note" style="margin-top:18px">Risk labels illustrate the interface. They are <strong>not assessments of real assets</strong>. Token identity and liquidity must be independently verified once live data is introduced.</div>`;}
function portfolioPage(){const p=portfolio(state),cutoff=range==='All time'?0:Date.now()-({'Today':1,'7 days':7,'30 days':30,'90 days':90}[range]||1)*86400000,closed=state.trades.filter(t=>t.side==='sell'&&t.time>=cutoff);const rows=Object.entries(p.positions).filter(([,v])=>v.quantity>1e-8);return heading('Practice portfolio','Your capital stays imaginary. Your research gets sharper.',btn(icon('download')+' Export trades','csv')+btn('Add practice funds','funds','', 'primary'))+metrics([['Total value',money(p.value),'Invented token prices'],['Available balance',money(state.cash),'Practice funds only'],['Unrealised P&L',money(p.unrealised),'Open practice positions',p.unrealised>=0?'positive':'negative'],['Realised P&L',money(p.realised),`${money(p.fees)} lifetime costs`,p.realised>=0?'positive':'negative']])+`<div class="spread" style="margin-bottom:16px"><h2>Positions & performance</h2>${rangeControl()}</div><section class="panel chart-panel"><div class="panel-head"><h2>Illustrative performance curve</h2><span class="pill">NOT YOUR TRADE HISTORY</span></div>${chart('portfolio-'+range)}<div class="panel-body note">This synthetic curve changes with the selected range. The balances and trade ledger below are calculated from your actual prototype actions. Historical equity snapshots are deferred.</div></section><section class="panel"><div class="panel-head"><h2>Open positions</h2><small>${rows.length} positions</small></div>${rows.length?`<div class="table-scroll"><table><thead><tr><th>Token</th><th>Quantity</th><th>Cost incl. fees</th><th>Value</th><th>Unrealised</th><th></th></tr></thead><tbody>${rows.map(([id,v])=>{const t=tokenBy(id),value=v.quantity*quote(t,state.step);return `<tr><td>${tokenCell(t)}</td><td class="mono">${v.quantity.toFixed(4)}</td><td>${money(v.cost)}</td><td>${money(value)}</td><td class="${value>=v.cost?'positive':'negative'}">${money(value-v.cost)}</td><td>${btn('Manage','token',`data-id="${id}"`)}</td></tr>`;}).join('')}</tbody></table></div>`:empty('A clean slate','Open a token to make your first practice purchase.',btn('Explore tokens','navigate','data-id="Discovery"','ghost'))}</section><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Trade ledger</h2><small>${closed.length} sells in selected rolling period · realised P&L above is lifetime</small></div>${state.trades.length?`<div class="table-scroll"><table><thead><tr><th>Time</th><th>Action</th><th>Token</th><th>Quantity</th><th>Price</th><th>Costs</th><th>Cash flow</th></tr></thead><tbody>${state.trades.filter(t=>t.time>=cutoff).slice().reverse().map(t=>`<tr><td class="muted">${new Date(t.time).toLocaleString('en-GB')}</td><td>${t.side==='buy'?'Practice buy':'Practice sell'}</td><td>${tokenBy(t.token).symbol}</td><td>${t.quantity.toFixed(4)}</td><td>${price(t.price)}</td><td>${money(t.fees)}</td><td>${t.side==='buy'?'−':'+'}${money(t.total)}</td></tr>`).join('')}</tbody></table></div>`:empty('No transactions yet','Practice transactions and modelled costs will appear here.')}</section><div class="note" style="margin-top:18px">Partial sells, slippage, fees and allocation limits work in this prototype. Closed-trade statistics use fee-inclusive average cost. Stop orders and historical backtesting require the later execution model.</div>`;}
function social(){const filtered=posts.filter(p=>(sourceFilter==='All sources'||p.source===sourceFilter)&&`${p.text} ${p.account}`.toLowerCase().includes(postSearch.toLowerCase()));return heading('Social intelligence','Context from a fictional research feed. No platform is connected.',btn('Connector availability','navigate','data-id="Data health"','ghost'))+`<div class="two-col"><section class="panel"><div class="filterbar"><input id="post-search" value="${esc(postSearch)}" placeholder="Search demo posts…" aria-label="Search demo posts"><select id="source-filter" aria-label="Source filter">${['All sources',...sources].map(v=>`<option ${v===sourceFilter?'selected':''}>${v}</option>`).join('')}</select><span class="grow"></span><span class="pill">FICTIONAL POSTS</span></div>${filtered.map(p=>`<article class="feed-post"><div class="spread"><div class="row"><span class="avatar">${p.account.split(' ').map(w=>w[0]).join('')}</span><div><h3>${p.account}</h3><small class="muted">${p.source} · invented account</small></div></div><small class="muted">${p.time} · fixture</small></div><p>${esc(p.text)}</p><div class="spread"><span class="pill">#${tokenBy(p.token).symbol}</span>${btn('Inspect context '+icon('arrow'),'token',`data-id="${p.token}"`,'text-button')}</div></article>`).join('')||empty('No matching posts','Select another source or search term.')}</section><aside class="stack"><section class="panel"><div class="panel-head"><h2>Monitoring keywords</h2><small>${state.settings.keywords.length}</small></div><div class="panel-body"><div class="chip-list">${state.settings.keywords.map((k,i)=>`<span class="chip">${esc(k)}${btn('×','remove-keyword',`data-id="${i}" aria-label="Remove ${esc(k)}"`)}</span>`).join('')}</div><form id="keyword-form" class="input-row"><input name="keyword" placeholder="Add keyword or #hashtag" aria-label="New monitoring keyword" maxlength="80" required><button aria-label="Add keyword">${icon('plus')}</button></form><small class="muted">Saved for future connectors. Demo feed is independently searchable.</small></div></section><section class="panel"><div class="panel-head"><h2>Account watchlist</h2>${btn(icon('plus'),'add-account','aria-label="Add watched account"','icon-btn')}</div><div class="panel-body">${state.settings.accounts.map((a,i)=>`<div class="account-card"><div class="spread"><strong>${esc(a.name)}</strong>${btn(icon('close'),'remove-account',`data-id="${i}" aria-label="Remove ${esc(a.name)}"`,'icon-btn')}</div><p>${esc(a.source)} · not connected</p><div class="spread"><select data-account="${i}" data-field="priority" aria-label="Priority for ${esc(a.name)}">${['High','Normal','Low'].map(v=>`<option ${a.priority===v?'selected':''}>${v}</option>`).join('')}</select><label class="row"><small>Instant alerts</small><input type="checkbox" data-account="${i}" data-field="alerts" ${a.alerts?'checked':''}></label></div><label><small class="muted">Account keywords</small><input style="width:100%;margin-top:5px" data-account="${i}" data-field="keywords" value="${esc(a.keywords)}" maxlength="200" aria-label="Keywords for ${esc(a.name)}"></label></div>`).join('')||'<p class="muted">No accounts saved.</p>'}</div></section></aside></div>`;}
function assistant(){const chat=state.chats.find(c=>c.id===state.activeChat);return heading('Research assistant','A place to question the signal, and keep the evidence close.',`<span class="pill">SCRIPTED DEMO · NO AI CONNECTED</span>`)+`<section class="panel chat-layout"><aside class="chat-list">${btn(icon('plus')+' New conversation','new-chat','', 'ghost')}<input id="chat-search" value="${esc(chatSearch)}" placeholder="Search conversations" aria-label="Search conversations">${state.chats.filter(c=>`${c.title} ${c.messages.map(m=>m.text).join(' ')}`.toLowerCase().includes(chatSearch.toLowerCase())).map(c=>btn(esc(c.title),'select-chat',`data-id="${esc(c.id)}"`,c.id===state.activeChat?'primary':'ghost')).join('')}</aside><div class="conversation"><div class="messages" id="messages">${chat.messages.length?chat.messages.map(m=>`<div class="message ${m.role}">${m.role==='assistant'?'<small>SENTINEL / SCRIPTED DEMO</small>':''}<span>${esc(m.text)}</span></div>`).join(''):`<div class="chat-intro">${icon('spark')}<h2>Start with a better question.</h2><p>Explore research workflows using invented data.<br>Responses are scripted. Your conversations stay on this device.</p><div class="prompts">${['Why is ORBIT trending?','How risky is this token?','How did my portfolio perform?','What happened while I was offline?'].map(q=>btn(esc(q)+' '+icon('arrow'),'prompt',`data-id="${esc(q)}"`)).join('')}</div></div>`}</div><form id="chat-form" class="compose"><textarea name="message" aria-label="Message the demo assistant" placeholder="Ask about your practice portfolio or a research signal…" maxlength="2000" required ${chatBusy?'disabled':''}></textarea><button class="primary" ${chatBusy?'disabled':''} aria-label="Send message">${icon('arrow')}</button></form><small class="muted" style="padding:0 17px 13px">${chatBusy?'Writing scripted response…':'No API requests. No verified market evidence. Ctrl+Enter to send.'}</small></div></section>`;}
function notifications(){const filtered=state.alerts.filter(a=>a.status!=='Dismissed');return heading('Notification centre','A persistent record of your simulated research alerts.',btn('Acknowledge all','ack-all')+btn(icon('plus')+' Test alert','test-alert','', 'primary'))+`<div class="notification-list">${filtered.map(a=>{const t=tokenBy(a.token),r=reviewAlert(a,quote(t,state.step));return `<article class="panel notification-card"><div><div class="row"><span class="pill ${r.expired?'':'blue'}">${r.expired?'SIGNAL EXPIRED':t.signal}</span><small>${esc(a.status)} · ${age(a.created)}</small></div><h2 style="margin-top:12px">${t.symbol} <span class="muted">/ ${t.name}</span></h2><p>${esc(a.reason)}</p><small class="${r.move>=0?'positive':'negative'}">PRICE MOVED ${signed(r.move)} SINCE ALERT · simulated</small></div><div class="toolbar">${btn('Open','alert',`data-id="${a.id}"`)}${a.status==='Pending'?btn('Acknowledge','ack',`data-id="${a.id}"`):''}${btn(icon('close'),'dismiss',`data-id="${a.id}" aria-label="Dismiss ${t.symbol} alert"`,'icon-btn')}</div></article>`;}).join('')||`<section class="panel">${empty('Nothing pending','Create a test alert to explore the notification workflow.')}</section>`}</div>`;}
function health(){return heading('Data health','Availability is explicit. Every connector is currently disconnected.',btn('Connection settings','navigate','data-id="Settings"','ghost'))+`<section class="panel"><div class="table-scroll"><table><thead><tr><th>Connector</th><th>Status</th><th>Access requirement</th><th></th></tr></thead><tbody>${[...sources,'Solana RPC','DEX Screener','Axiom'].map((s,i)=>`<tr><td>${s}</td><td class="muted">${s==='Axiom'?'Unverified official API':'Not connected'}</td><td class="muted">${['Developer access & usage budget','Approved API access / OAuth','API project & quota','Bot invited to permitted chats','Bot permissions & message intent','Publisher-permitted feed','Public address & provider quota','Public documented API limits','Official authorisation not established'][i]}</td><td>${btn('Requirements','connector',`data-id="${esc(s)}"`,'ghost')}</td></tr>`).join('')}</tbody></table></div></section><div class="two-col" style="margin-top:20px"><section class="panel"><div class="panel-head"><h2>Pipeline latency</h2><span class="pill">NOT MEASURED</span></div><div class="panel-body"><div class="source-row"><span>Source publication → detection</span><small>Unavailable</small></div><div class="source-row"><span>Market data retrieval</span><small>Unavailable</small></div><div class="source-row"><span>AI enrichment</span><small>Not running</small></div><div class="source-row"><span>Notification delivery</span><small>In-app demo only</small></div></div></section><section class="panel"><div class="panel-head"><h2>Overnight report</h2></div><div class="panel-body"><p class="muted">No collector is running. There are no verified overnight events to report.</p><div class="note" style="margin-top:15px">Closing this preview stops simulation. No 24/7 service or cloud monitoring is configured.</div></div></section></div>`;}

const schemas={
 Appearance:[['Theme','theme','select',['Charcoal','Graphite','Light'],'Surface palette'],['Accent colour','accent','color',null,'Native colour wheel with editable HEX'],['Glass appearance','acrylic','check',null,'Blurs content inside the page; not the desktop wallpaper'],['Transparency','transparency','range',[0,40,1],'% · surface transparency'],['Blur intensity','blur','range',[0,40,1],'px · browser content blur'],['Corner radius','radius','range',[0,28,1],'px'],['Shadow strength','shadow','range',[0,60,1],'px · alert popup'],['Font size','fontSize','range',[11,18,1],'px · base interface text'],['UI density','density','select',['Compact','Comfortable'],'Spacing between major sections'],['Transition duration','motion','range',[120,180,10],'ms'],['Reduce motion','reduceMotion','check',null,'System reduced-motion preference is also respected'],['Profit colour','profit','color',null,'Chart and positive values'],['Loss colour','loss','color',null,'Chart and negative values'],['Chart rendering','chartStyle','select',['Candles','Line'],'Synthetic chart style']],
 AI:[['Provider','aiProvider','select',['Scripted demo','Ollama (not connected)','OpenAI (not connected)'],'Selection is saved; no provider is called in Phase 1'],['Model preference','model','text',null,'Saved only; model discovery is deferred'],['Ollama server','ollama','text',null,'Saved only; no network connection'],['Maximum analysis time','aiTimeout','range',[1,30,1],'seconds · future pipeline preference'],['Evidence threshold','threshold','range',[0,100,5],'% · future screening preference, not profit probability'],['AI concurrency','aiConcurrency','range',[1,4,1],'future inference jobs']],
 'Social monitoring':[['Monitoring interval','frequency','range',[10,120,5],'seconds · future connectors'],['Source priority','sourcePriority','select',['Balanced','Watchlisted accounts','News first'],'Future connector scheduling']],
 Notifications:[['Enable test notifications','notifications','check',null,'In-app preview only; alerts still save in the centre'],['Notification sound','sound','check',null,'Opt-in tone when Test alert is pressed'],['Sound volume','volume','range',[0,100,5],'%'],['Monitor preference','monitor','select',['Primary','Secondary (preview only)'],'Saved; browser cannot choose a Windows monitor'],['Popup position','position','select',['Bottom right','Bottom left','Top right','Top left'],'Position inside this browser viewport'],['Persistent popup','persistent','check',null,'When off, popup closes after 12 seconds; centre retains alerts'],['Quiet hours','quiet','check',null,'Suppress test popups during the local-time interval'],['Quiet hours start','quietStart','time',null,'Uses the browser local timezone'],['Quiet hours end','quietEnd','time',null,'Equal start and end means quiet all day'],['Alert categories','category','select',['All research signals','High interest only','Risk only'],'Filters which test alerts show a popup'],['Minimum liquidity','minLiquidity','number',null,'Fixture liquidity required for test popup']],
 Portfolio:[['Display currency','currency','select',['GBP','USD','EUR'],'Prototype values are relabelled; no foreign exchange conversion'],['Refresh interval','refresh','range',[3,60,1],'seconds · future wallet provider preference'],['History preference','history','select',['Today','7 days','30 days','90 days','All time'],'Saved default research window'],['Slippage assumption','slippage','range',[0,10,.1],'% · applied to practice fills'],['Trading fee','fee','range',[0,5,.1],'% · applied to practice fills'],['Network fee','networkFee','number',null,'Display currency per practice fill'],['Max position allocation','maxPosition','range',[1,100,1],'% of practice starting capital'],['Portfolio loss limit','maxLoss','range',[1,100,1],'% · blocks new buys after this drawdown'],['Simulate failed fills','failedTransactions','check',null,'Every fourth attempted fill fails until disabled; no fees charged']],
 Performance:[['Hardware acceleration preference','acceleration','check',null,'Saved only; browser controls actual acceleration'],['Background processing preference','background','check',null,'Saved only; no background service is installed'],['Memory budget','memory','range',[128,1024,64],'MB · future worker budget'],['Cache budget','cache','range',[16,256,16],'MB · future market cache'],['Data retention','retention','range',[7,180,1],'days · future database policy'],['Logging','logging','select',['Errors','Warnings','Verbose'],'Future worker logging preference']]
};
function settingRow([label,key,type,options,note]){const v=state.settings[key],id='s-'+key;let control='';if(type==='check')control=`<input id="${id}" type="checkbox" data-setting="${key}" ${v?'checked':''}>`;else if(type==='select')control=`<select id="${id}" data-setting="${key}">${options.map(o=>`<option ${o===v?'selected':''}>${o}</option>`).join('')}</select>`;else if(type==='range')control=`<input id="${id}" type="range" min="${options[0]}" max="${options[1]}" step="${options[2]}" value="${v}" data-setting="${key}"><output for="${id}">${v}</output>`;else if(type==='color')control=`<input id="${id}" type="color" value="${esc(v)}" data-setting="${key}" aria-label="${label} wheel"><input type="text" value="${esc(v)}" data-setting="${key}" pattern="#[0-9a-fA-F]{6}" maxlength="7" aria-label="${label} HEX" style="width:96px">`;else control=`<input id="${id}" type="${type}" value="${esc(v)}" data-setting="${key}" ${type==='number'?'min="0" max="1000000" step="0.01"':'maxlength="300"'}>`;return `<div class="setting-row"><div><label for="${id}">${label}</label><p>${note}</p></div><div class="setting-controls">${control}</div></div>`;}
function settings(){return heading('Make it yours.','Preferences save automatically on this device.',btn(icon('download')+' Export backup','backup')+btn('Restore backup','restore'))+`<div class="settings-layout"><nav class="settings-tabs" aria-label="Settings categories">${Object.keys(schemas).map(v=>btn(v,'settings-tab',`data-id="${v}" aria-pressed="${settingsTab===v}"`,settingsTab===v?'selected':'')).join('')}${btn('Data & privacy','settings-tab','data-id="Data & privacy"',settingsTab==='Data & privacy'?'selected':'')}</nav><div class="stack"><section class="panel"><div class="panel-head"><h2>${settingsTab}</h2><small>Saved automatically</small></div>${settingsTab==='Appearance'?`<div class="appearance-sample"><span class="coin" style="color:var(--accent)">${icon('shield')}</span><div class="grow"><h3>A little less noise.</h3><p>Your research, in your colours.</p></div><span class="pill blue">PREVIEW</span></div>`:''}<div class="setting-group">${settingsTab==='Data & privacy'?`<div class="setting-row"><div><h3>Your data stays here</h3><p>No analytics, network requests or credentials. Backups include chat history and practice positions.</p></div></div><div class="setting-row"><div><h3>Reset all prototype data</h3><p>Requires confirmation. Export a backup first.</p></div>${btn('Reset prototype','reset','', 'danger')}</div>`:schemas[settingsTab].map(settingRow).join('')}</div></section>${settingsTab==='Social monitoring'?`<div class="note">API credentials are intentionally absent in this offline prototype. Manage keywords and account priorities on the Social intelligence page. ${btn('Open monitoring lists','navigate','data-id="Social intelligence"','text-button')}</div>`:''}${settingsTab==='Portfolio'?`<section class="panel"><div class="panel-head"><h2>Read-only wallet list</h2><span class="pill">NOT SYNCED</span></div><div class="panel-body">${state.settings.wallets.map((w,i)=>`<div class="source-row"><span class="mono" style="overflow-wrap:anywhere;max-width:85%">${esc(w)}</span>${btn(icon('close'),'remove-wallet',`data-id="${i}" aria-label="Remove wallet"`,'icon-btn')}</div>`).join('')}<form id="wallet-form" class="input-row"><input name="wallet" placeholder="Public Solana address only" aria-label="Public wallet address" maxlength="44" required><button>Add address</button></form><div class="note" style="margin-top:12px">Stored as a watchlist preference only. No balance queries. Never enter a seed phrase or private key.</div></div></section>`:''}${settingsTab==='AI'?`<div class="note">Provider selection does not connect a service. The assistant continues to use scripted demo replies. OpenAI API access is a separate service; no credentials are collected here.</div>`:''}${settingsTab==='Appearance'?`<div class="note">Browser glass can blur page content behind the popup. It cannot reproduce Windows desktop-background acrylic. Native compositor support, transparency-disabled fallback and multi-monitor behaviour remain future verification work.</div>`:''}</div></div>`;}

const routes=[['Dashboard','grid'],['Discovery','compass'],['Portfolio','wallet'],['Social intelligence','social'],['AI assistant','spark'],['Notifications','bell'],['Data health','shield'],['Settings','settings']];
function render(){
 if(!routes.some(([r])=>r===route))route='Dashboard';
 const page={Dashboard:dashboard,Discovery:discovery,Portfolio:()=>portfolioPage()+statisticsPanel(),'Social intelligence':social,'AI assistant':assistant,Notifications:notifications,'Data health':health,Settings:settings}[route];
 app.innerHTML=`${storageError?`<div class="storage-error" role="alert">${esc(storageError)}</div>`:''}<div class="shell"><aside class="sidebar"><div class="brand"><svg viewBox="0 0 30 34" fill="none" aria-hidden="true"><path d="M15 2L27 8v10c0 7-12 14-12 14S3 25 3 18V8L15 2Z" stroke="currentColor" stroke-width="1.5"/><path d="M10 12h10l-10 9h10" stroke="currentColor" stroke-width="1.5"/></svg><span>SENTINEL</span></div><div class="nav-group">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${routes.slice(0,5).map(([r,i])=>btn(icon(i)+`<span>${r}</span>`,'navigate',`data-id="${r}" ${r===route?'aria-current="page"':''}`,r===route?'active':'')).join('')}</nav><div class="nav-group" style="margin-top:20px">MONITORING</div><nav class="nav" aria-label="Monitoring">${routes.slice(5,7).map(([r,i])=>btn(icon(i)+`<span>${r}</span>${r==='Notifications'?`<b class="count">${state.alerts.filter(a=>a.status==='Pending').length}</b>`:''}`,'navigate',`data-id="${r}" ${r===route?'aria-current="page"':''}`,r===route?'active':'')).join('')}</nav><div class="sidebar-bottom"><nav class="nav">${btn(icon('settings')+'<span>Settings</span>','navigate','data-id="Settings"',route==='Settings'?'active':'')}</nav><div class="local-status"><span><i class="dot"></i>Local simulation</span><small class="muted">v0.1 · Design review</small><small class="muted">No live connections</small></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">Workspace <span>/ &nbsp;${route}</span></div><form id="global-search" class="search">${icon('search')}<input name="query" placeholder="Find a token…" aria-label="Find a token" autocomplete="off"><kbd>Ctrl K</kbd></form><div class="mode">SIMULATION</div>${btn(icon('bell'),'navigate','data-id="Notifications" aria-label="Notification centre"','icon-btn')}<span class="avatar" title="Local profile">S</span></header><main class="main" id="main">${page()}<footer class="footer"><span>All market values, posts and signals are simulated.</span><span>${state.settings.simulation?'Simulation playing · 5s updates':'Simulation paused'} &nbsp;·&nbsp; Local preferences ${storageError?'not saved':'saved'}</span></footer></main></div></div><div id="popup-root"></div><div class="toast-stack" id="toast-stack" aria-live="polite"></div><dialog id="modal" class="dialog" aria-labelledby="dialog-title"></dialog><input id="restore-file" type="file" accept="application/json,.json" hidden>`;
 renderPopup();if(route==='AI assistant')document.querySelector('#messages')?.scrollTo(0,999999);
}
function navigate(target){route=target;location.hash=target;render();document.querySelector('h1')?.setAttribute('tabindex','-1');document.querySelector('h1')?.focus({preventScroll:true});}
function toast(message){const modal=document.querySelector('#modal'),area=modal?.open?modal.querySelector('.dialog-body'):document.querySelector('#toast-stack');const item=document.createElement('div');item.className='toast';item.setAttribute('role','status');item.innerHTML=`${icon('check')}<span>${esc(message)}</span>${btn(icon('close'),'close-toast','aria-label="Close message"','icon-btn')}`;area.append(item);if(!modal?.open)while(area.children.length>3)area.firstChild.remove();document.querySelector('#announcer').textContent=message;setTimeout(()=>item.remove(),6000);}
function showDialog(title,html){const modal=document.querySelector('#modal');modal.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2>${btn(icon('close'),'close-dialog','aria-label="Close dialog"','icon-btn')}</div><div class="dialog-body">${html}</div>`;modal.showModal();}
function openToken(id){modalToken=id;tradeSide='buy';tokenDialog();}
function tokenDialog(){const t=tokenBy(modalToken),held=holdings(state)[t.id]?.quantity||0;showDialog(`${t.symbol} / ${t.name}`,`<div class="spread"><span class="pill blue">SIMULATED TOKEN</span>${btn(icon('star')+(state.watchlist.includes(t.id)?' Saved':' Save'),'watch-modal',`data-id="${t.id}"`)}</div><div class="chart-summary" style="margin:18px 0"><strong>${price(quote(t,state.step))}</strong><span class="${t.change>=0?'positive':'negative'}">${signed(t.change)}</span></div>${chart(t.id)}<div class="token-facts">${[['Liquidity',compact(t.liquidity)],['24h volume',compact(t.volume)],['Market cap',compact(t.cap)],['Risk label',t.risk]].map(([k,v])=>`<div><small>${k}</small><strong>${v}</strong></div>`).join('')}</div><div class="note"><strong>${t.signal}</strong> · Invented evidence for interface testing. Holder concentration, permissions and developer activity are unverified. No real token contract is attached.</div><div class="toolbar" style="margin-top:14px">${btn(icon('copy')+' Copy fixture ID','copy',`data-id="SIM-${t.symbol}"`)}${btn('Axiom availability','connector','data-id="Axiom"')}${btn('Explain in assistant','explain',`data-id="${t.id}"`)}</div><form id="trade-form" class="trade-form"><div class="spread"><h3>Practice trade</h3><div class="segment">${['buy','sell'].map(v=>btn(v==='buy'?'Buy':'Sell','trade-side',`data-id="${v}"`,tradeSide===v?'selected':'')).join('')}</div></div><p class="muted" style="font-size:11px;margin:10px 0">Available ${money(state.cash)} · held ${held.toFixed(4)} ${t.symbol}</p><div class="row"><label class="grow">${tradeSide==='buy'?`Spend (${state.settings.currency}), before fees`:`Sell quantity (${t.symbol})`}<input type="number" name="amount" min="0.000001" step="any" value="${tradeSide==='buy'?'2':held.toFixed(6)}" required></label><button class="primary" ${tradeSide==='sell'&&held<=0?'disabled':''}>Review ${tradeSide==='buy'?'purchase':'sale'}</button></div><div class="note">Slippage ${state.settings.slippage}% · fee ${state.settings.fee}% + ${money(state.settings.networkFee)} network assumption. Possible loss: entire practice position. No real orders.</div></form>`);}
function quietNow(){if(!state.settings.quiet)return false;const d=new Date(),now=d.getHours()*60+d.getMinutes(),toMinutes=t=>{const [h,m]=t.split(':').map(Number);return h*60+m;},start=toMinutes(state.settings.quietStart),end=toMinutes(state.settings.quietEnd);return start===end|| (start<end?now>=start&&now<end:now>=start||now<end);}
function renderPopup(){const root=document.querySelector('#popup-root');if(!popup){root.innerHTML='';return;}const a=state.alerts.find(a=>a.id===popup);if(!a){popup=null;root.innerHTML='';return;}const t=tokenBy(a.token),r=reviewAlert(a,quote(t,state.step)),pos=state.settings.position;root.innerHTML=`<aside class="alert-popup ${pos.startsWith('Top')?'top':''} ${pos.endsWith('left')?'left':''}" aria-label="Simulated persistent alert"><div class="panel-head"><span class="pill ${r.expired?'':'blue'}">${r.expired?'SIGNAL EXPIRED':t.signal}</span>${btn(icon('close'),'hide-popup','aria-label="Close popup; keep alert in centre"','icon-btn')}</div><div class="panel-body"><div class="spread"><h2>${t.symbol} <span class="muted">/ ${t.name}</span></h2><span class="mono">${price(quote(t,state.step))}</span></div><p>${esc(a.reason)}</p><small class="${r.move>=0?'positive':'negative'}">PRICE MOVED ${signed(r.move)} SINCE ALERT</small></div>${chart(t.id)}<div class="panel-body"><div class="mini-stats"><div><small>Liquidity</small><strong>${compact(t.liquidity)} ${state.settings.currency}</strong></div><div><small>Risk / confidence</small><strong>${t.risk} / demo only</strong></div></div><p>Fixture source · ${age(a.created)} · not a live feed</p><div class="popup-actions">${btn('Inspect / practice','token',`data-id="${t.id}"`,'primary')}${btn(icon('star'),'watch',`data-id="${t.id}" aria-label="Toggle watchlist"`)}${btn('Acknowledge','ack',`data-id="${a.id}"`)}${btn('Dismiss','dismiss',`data-id="${a.id}"`)}</div></div></aside>`;}
function testAlert(){const eligible=tokens.filter(t=>t.liquidity>=state.settings.minLiquidity);const t=eligible[state.alerts.length%eligible.length];if(!t){toast('No fixture meets your minimum liquidity filter.');return;}const alert={id:crypto.randomUUID(),token:t.id,status:'Pending',created:Date.now(),base:quote(t,state.step),reason:'Test alert: invented social activity and fixture liquidity passed the demo filter.'};state.alerts.push(alert);state.alerts=state.alerts.slice(-500);commit();const category=state.settings.category,match=category==='All research signals'||category==='High interest only'&&t.signal==='HIGH INTEREST'||category==='Risk only'&&['High','Critical'].includes(t.risk);if(!state.settings.notifications||quietNow()||!match){toast('Test alert saved. Popup suppressed by notification preferences.');return;}popup=alert.id;renderPopup();if(!state.settings.persistent)setTimeout(()=>{if(popup===alert.id){popup=null;renderPopup();}},12000);if(state.settings.sound)playTone();}
function playTone(){try{const context=new AudioContext(),osc=context.createOscillator(),gain=context.createGain();gain.gain.value=state.settings.volume/100*.06;osc.frequency.value=620;osc.connect(gain);gain.connect(context.destination);osc.start();osc.stop(context.currentTime+.1);osc.onended=()=>context.close();}catch{toast('Browser audio unavailable.');}}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCSV(){const lines=[['time_utc','side','fixture_token','quantity','price','fees','cash_flow','currency'],...state.trades.map(t=>[new Date(t.time).toISOString(),t.side,tokenBy(t.token).symbol,t.quantity,t.price,t.fees,(t.side==='buy'?-1:1)*t.total,state.settings.currency])];download('sentinel-practice-trades.csv',lines.map(row=>row.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\r\n'),'text/csv');toast('Practice trade ledger exported.');}
async function sendChat(text){if(chatBusy||!text.trim())return;const chat=state.chats.find(c=>c.id===state.activeChat);if(chat.messages.length>=200){toast('Conversation limit reached. Start a new conversation.');return;}chatBusy=true;chat.messages.push({role:'user',text:text.slice(0,2000)});if(chat.messages.length===1)chat.title=text.slice(0,30);const reply=demoReply(text,state);chat.messages.push({role:'assistant',text:''});commit();const message=chat.messages.at(-1);const words=reply.split(' ');for(let i=0;i<words.length;i+=4){await new Promise(r=>setTimeout(r,state.settings.reduceMotion?0:30));message.text=words.slice(0,i+4).join(' ');if(route==='AI assistant'&&state.activeChat===chat.id){const node=document.querySelector('.message.assistant:last-child span');if(node)node.textContent=message.text;document.querySelector('#messages')?.scrollTo(0,999999);}}message.text=reply;chatBusy=false;commit();}

app.addEventListener('click',async e=>{
 const el=e.target.closest('[data-action]');if(!el)return;const id=el.dataset.id,action=el.dataset.action;
 if(action==='navigate')navigate(id);
 else if(action==='watch'||action==='watch-modal'){const i=state.watchlist.indexOf(id);if(i<0)state.watchlist.push(id);else state.watchlist.splice(i,1);commit(action!=='watch-modal');if(action==='watch-modal'){document.querySelector('#modal').close();tokenDialog();}else toast(i<0?'Token saved to watchlist.':'Token removed from watchlist.');}
 else if(action==='token'){popup=null;renderPopup();openToken(id);}
 else if(action==='close-dialog')document.querySelector('#modal').close();
 else if(action==='close-toast')el.closest('.toast').remove();
 else if(action==='test-alert')testAlert();
 else if(action==='simulation'){state.settings.simulation=!state.settings.simulation;commit();}
 else if(action==='range'){range=id;render();}
 else if(action==='chart-style'){state.settings.chartStyle=id;commit();}
 else if(action==='watch-only'){watchOnly=!watchOnly;render();}
 else if(action==='settings-tab'){settingsTab=id;render();}
 else if(action==='alert'){popup=id;renderPopup();}
 else if(action==='hide-popup'){popup=null;renderPopup();}
 else if(action==='ack'||action==='dismiss'){state.alerts.find(a=>a.id===id).status=action==='ack'?'Acknowledged':'Dismissed';if(popup===id)popup=null;commit();}
 else if(action==='ack-all'){state.alerts.forEach(a=>{if(a.status==='Pending')a.status='Acknowledged';});popup=null;commit();}
 else if(action==='remove-keyword'){state.settings.keywords.splice(Number(id),1);commit();}
 else if(action==='remove-account'){state.settings.accounts.splice(Number(id),1);commit();}
 else if(action==='remove-wallet'){state.settings.wallets.splice(Number(id),1);commit();}
 else if(action==='add-account')showDialog('Watch a public account',`<form id="account-form" class="stack"><label class="stack">Public account name<input name="account" maxlength="80" placeholder="@research_account" required></label><label class="stack">Platform<select name="source">${sources.map(s=>`<option>${s}</option>`).join('')}</select></label><div class="note">This saves a monitoring preference. No account connection or real post collection occurs.</div><button class="primary">Save account</button></form>`);
 else if(action==='new-chat'){if(state.chats.length>=50){toast('50 conversation limit reached. Export and reset to clear.');return;}const c={id:crypto.randomUUID(),title:'New research',messages:[]};state.chats.unshift(c);state.activeChat=c.id;commit();}
 else if(action==='select-chat'){state.activeChat=id;commit();}
 else if(action==='prompt')await sendChat(id);
 else if(action==='explain'){document.querySelector('#modal').close();navigate('AI assistant');await sendChat(`How risky is ${tokenBy(id).symbol}?`);}
 else if(action==='trade-side'){tradeSide=id;document.querySelector('#modal').close();tokenDialog();}
 else if(action==='confirm-trade'){try{state=trade(state,{token:el.dataset.token,side:el.dataset.side,amount:Number(el.dataset.amount)});document.querySelector('#modal').close();commit();toast('Practice trade recorded. No real transaction occurred.');}catch(error){toast(error.message);}}
 else if(action==='copy'){try{await navigator.clipboard.writeText(id);toast('Fictional fixture ID copied; this is not a contract address.');}catch{showDialog('Copy fixture ID',`<input readonly value="${esc(id)}" aria-label="Fictional fixture ID"><p class="muted">Select and copy manually. This is not a real contract.</p>`);}}
 else if(action==='connector'){const details={Axiom:'No official developer API or supported token deep-link format was identified in the official documentation index. Future alternatives: public-wallet RPC and transaction CSV import. No account integration exists in this prototype.','X / Twitter':'Requires authorised developer access and a usage budget. No scraping or browser credentials.','Reddit':'Requires approved access and compliance with Reddit API policies. No unrestricted collection is assumed.','YouTube':'Requires a Google API project and quota; private/user data requires OAuth.','Telegram':'A bot must be added to permitted chats; bot privacy and channel permissions apply.','Discord':'Use an authorised bot with server permissions and message-content access when required.','RSS / News':'Only publisher-permitted RSS feeds. Respect refresh limits and redistribution terms.','Solana RPC':'Public addresses only. Provider rate limits apply; no seed phrases or signing methods.','DEX Screener':'Official public market endpoints have per-route limits. Token profiles are not complete or verified launch coverage.'};if(document.querySelector('#modal').open)document.querySelector('#modal').close();showDialog(`${esc(id)} / access requirements`,`<p style="line-height:1.9">${esc(details[id])}</p><div class="note" style="margin-top:16px">Phase 1 status: not connected. No API credentials are collected.</div>`);}
 else if(action==='backup'){download('sentinel-prototype-backup.json',JSON.stringify(state,null,2),'application/json');toast('Backup exported. Keep it private; it includes your chats.');}
 else if(action==='restore')document.querySelector('#restore-file').click();
 else if(action==='csv')exportCSV();
 else if(action==='funds')showDialog('Practice capital',`<form id="funds-form" class="stack"><p class="muted">Add fictional funds to this ledger. This increases starting capital for allocation limits.</p><div class="segment">${[10,50,100].map(v=>btn(money(v),'fund-preset',`data-id="${v}"`)).join('')}</div><label class="stack">Amount to add (${state.settings.currency})<input name="funds" type="number" min="1" max="100000" value="10" required></label><button class="primary">Add practice funds</button></form>`);
 else if(action==='fund-preset')document.querySelector('[name=funds]').value=id;
 else if(action==='reset')showDialog('Reset prototype data?',`<div class="stack"><p>All preferences, conversations, alerts and practice trades on this browser will be removed. Export a backup first.</p>${btn('Delete local prototype data','confirm-reset','', 'danger')}${btn('Keep my data','close-dialog')}</div>`);
 else if(action==='confirm-reset'){if(chatBusy){toast('Wait for the scripted reply to finish before resetting.');return;}state=initialState();popup=null;document.querySelector('#modal').close();commit();toast('Prototype reset.');}
});
app.addEventListener('submit',e=>{
 e.preventDefault();const form=e.target,data=new FormData(form);
 if(form.id==='global-search'){tokenFilter=String(data.get('query'));navigate('Discovery');}
 else if(form.id==='keyword-form'){const value=String(data.get('keyword')).trim();if(value&&!state.settings.keywords.includes(value)&&state.settings.keywords.length<200){state.settings.keywords.push(value);commit();}}
 else if(form.id==='account-form'){state.settings.accounts.push({name:String(data.get('account')).trim(),source:String(data.get('source')),priority:'Normal',alerts:true,keywords:''});document.querySelector('#modal').close();commit();}
 else if(form.id==='wallet-form'){const value=String(data.get('wallet')).trim();if(!/^[1-9A-HJ-NP-Za-km-z]{32,44}$/.test(value)){toast('Enter a public Solana address using base58 characters (32–44 characters).');return;}if(!state.settings.wallets.includes(value))state.settings.wallets.push(value);commit();toast('Public address saved. No balance query was made.');}
 else if(form.id==='funds-form'){const amount=Number(data.get('funds'));if(!Number.isFinite(amount)||amount<=0||amount>100000)return;state.cash+=amount;state.settings.initialBalance+=amount;document.querySelector('#modal').close();commit();toast('Fictional practice funds added.');}
 else if(form.id==='trade-form'){const amount=Number(data.get('amount'));try{const next=trade(state,{token:modalToken,side:tradeSide,amount}),t=next.trades.at(-1);document.querySelector('#modal').close();showDialog('Review practice transaction',`<div class="stack"><span class="pill blue">SIMULATION ONLY</span><p>${tradeSide==='buy'?'Buy':'Sell'} ${t.quantity.toFixed(6)} ${tokenBy(modalToken).symbol} at ${price(t.price)} ${state.settings.currency}.</p><p>Estimated costs ${money(t.fees)} · ${tradeSide==='buy'?'Debited':'Received'} ${money(t.total)}.</p><div class="note">Fill includes ${state.settings.slippage}% slippage. Fictional liquidity, immediate fill, no latency model. You could lose the entire position in a real market.</div>${btn('Confirm practice transaction','confirm-trade',`data-token="${modalToken}" data-side="${tradeSide}" data-amount="${amount}"`,'primary')}${btn('Cancel','close-dialog')}</div>`);}catch(error){toast(error.message);}}
 else if(form.id==='chat-form')sendChat(String(data.get('message')));
});
function updateSetting(el){const key=el.dataset.setting,previous=state.settings[key];let value=el.type==='checkbox'?el.checked:typeof defaults[key]==='number'?Number(el.value):el.value;if(el.type!=='checkbox'&&!el.checkValidity())return;if(typeof previous==='number'&&!Number.isFinite(value))return;if(['accent','profit','loss'].includes(key)&&!/^#[0-9a-f]{6}$/i.test(value))return;state.settings[key]=value;commit(false);if(el.type==='range'){const output=el.parentElement.querySelector('output');if(output)output.textContent=value;}if(el.type==='color')el.parentElement.querySelector('input[type=text]').value=value;else if(['accent','profit','loss'].includes(key))el.parentElement.querySelector('input[type=color]').value=value;if(key==='position')renderPopup();}
app.addEventListener('input',e=>{const el=e.target;if(el.dataset.setting){updateSetting(el);return;}const map={'token-search':v=>tokenFilter=v,'post-search':v=>postSearch=v,'chat-search':v=>chatSearch=v};if(map[el.id]){const id=el.id,pos=el.selectionStart;map[id](el.value);render();const next=document.getElementById(id);next.focus();next.setSelectionRange(pos,pos);}});
app.addEventListener('change',async e=>{const el=e.target;if(el.dataset.setting){updateSetting(el);return;}if(el.dataset.account){const a=state.settings.accounts[Number(el.dataset.account)];a[el.dataset.field]=el.type==='checkbox'?el.checked:el.value;commit(false);return;}if(el.id==='risk-filter'){riskFilter=el.value;render();}if(el.id==='sort'){sort=el.value;render();}if(el.id==='source-filter'){sourceFilter=el.value;render();}if(el.id==='restore-file'){const file=el.files[0];if(!file)return;try{if(file.size>2000000)throw Error('Backup exceeds 2 MB.');const restored=validateState(JSON.parse(await file.text()));if(chatBusy)throw Error('Wait for the scripted reply to finish before restoring.');showDialog('Restore backup?',`<div class="stack"><p>Replace current prototype data with ${restored.trades.length} trades, ${restored.chats.length} conversations and saved preferences?</p><form id="restore-confirm"><button class="primary">Replace current data</button></form>${btn('Cancel','close-dialog')}</div>`);document.querySelector('#restore-confirm').addEventListener('submit',ev=>{ev.preventDefault();state=restored;popup=null;document.querySelector('#modal').close();commit();toast('Backup restored.');},{once:true});}catch(error){toast(error.message);}el.value='';}});
app.addEventListener('pointermove',e=>{const svg=e.target.closest('[data-chart]');if(!svg)return;const tooltip=svg.parentElement.querySelector('.chart-tooltip');if(!tooltip)return;const rect=svg.getBoundingClientRect(),index=Math.max(0,Math.min(63,Math.round((e.clientX-rect.left)/rect.width*63))),point=series(svg.dataset.chart,64,state.step)[index];tooltip.hidden=false;tooltip.textContent=`Sample ${index+1} · O ${point.open.toFixed(2)} H ${point.high.toFixed(2)} L ${point.low.toFixed(2)} C ${point.close.toFixed(2)} · synthetic index`;});
app.addEventListener('pointerout',e=>{const svg=e.target.closest('[data-chart]');if(svg&&!svg.contains(e.relatedTarget)){const tip=svg.parentElement.querySelector('.chart-tooltip');if(tip)tip.hidden=true;}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('[name=query]')?.focus();}if(e.ctrlKey&&e.key==='Enter'&&e.target.closest('#chat-form')){e.preventDefault();e.target.closest('form').requestSubmit();}});
window.addEventListener('hashchange',()=>{route=decodeURIComponent(location.hash.slice(1));render();});
window.addEventListener('storage',e=>{if(e.key==='sentinel.prototype.v1'){toast('Another tab updated preferences. Reload to use its changes.');}});
// Single bounded timer, suspended while hidden; no network polling or background workers.
setInterval(()=>{if(!state.settings.simulation||document.hidden||document.querySelector('#modal')?.open||chatBusy)return;state.step++;storageError=save(storage,state);const active=document.activeElement;if(!['INPUT','TEXTAREA','SELECT'].includes(active?.tagName))render();},5000);
applyTheme();render();
